//! Checks of intersection results for the SMLib intersection suites (`smlib_ssi_advanced`,
//! `smlib_ssi_analytic`, `smlib_cci`, generated by `tools/smlib_to_rust.py`). Not part of
//! `smlib_common` itself (the other suites don't need it): a suite includes it with
//! `#[path = "smlib_common/intersect.rs"] mod intersect;`.
//!
//! SMLib intersects surfaces on their faces' uv boxes and counts curves its own way (seams,
//! degenerate curves, coincident regions), so counts are compared only as none against some.
//! What is checked:
//! - every point of the curves inside both faces lies on both surfaces ([`ON_TOL`]);
//! - the length of the curves inside both faces against SMLib's (the oracle's), to 1e-3: faces
//!   as SMLib takes them ([`Patch::domain`]: untrimmed, over their uv domains) where the suite
//!   intersects B-rep faces;
//! - every sample point SMLib's curves pass through lies near one of ours ([`SAMPLE_TOL`]).
#![allow(dead_code)]

use cadrs_kernel::native::classify::{self, InFace};
use cadrs_kernel::native::curve::Curve;
use cadrs_kernel::native::math::*;
use cadrs_kernel::native::ssi;
use cadrs_kernel::native::surface::Surface;
use cadrs_kernel::native::topo::Body;

pub type UvBox = ((f64, f64), (f64, f64));

/// A point of an intersection lies on a surface within this (mm): the approximation tolerance
/// SMLib's tests intersect with (`my_test_ssi(.., 1.0e-3, ..)`).
pub const ON_TOL: f64 = 1e-3;
/// SMLib's sample points lie within this of our curves: its approximation tolerance (1e-3)
/// with a margin.
pub const SAMPLE_TOL: f64 = 2e-3;
/// Relative tolerance on the total length (absolute below 1 mm).
pub const LEN_TOL: f64 = 1e-3;

/// Distance from `p` to the surface: exact for the analytic ones, else the better of two
/// projections (a Newton from the default start and one from a coarse grid).
pub fn dist(s: &Surface, p: &P3) -> f64 {
    if let Some(d) = s.signed_distance(p) {
        return d.abs();
    }
    feet(s, p, None).into_iter().map(|(u, v)| (s.eval(u, v) - p).norm()).fold(f64::INFINITY, f64::min)
}

/// Distance from `p` to `s`, Newton from the foot of the point before (`hint`, updated), or a
/// global search ([`feet`]) when that comes out farther than [`ON_TOL`].
pub fn dist_along(s: &Surface, p: &P3, hint: &std::cell::Cell<Option<(f64, f64)>>) -> f64 {
    if let Some(d) = s.signed_distance(p) {
        return d.abs();
    }
    if let Some(h) = hint.get() {
        let (u, v) = s.project(p, Some(h));
        let d = (s.eval(u, v) - p).norm();
        if d <= ON_TOL {
            hint.set(Some((u, v)));
            return d;
        }
    }
    let best = feet(s, p, None).into_iter().map(|(u, v)| ((s.eval(u, v) - p).norm(), (u, v))).fold((f64::INFINITY, (0.0, 0.0)), |x, y| if y.0 < x.0 { y } else { x });
    hint.set(Some(best.1));
    best.0
}

/// Candidate feet of `p` on `s`: Newton from the default start, from the nearest points of a
/// coarse and a fine grid over the surface's range (or `uv` where that is unbounded), and from
/// both sides of a closed surface's seam (where Newton stops).
pub fn feet(s: &Surface, p: &P3, uv: Option<UvBox>) -> Vec<(f64, f64)> {
    let mut out = vec![s.project(p, None)];
    if matches!(s, Surface::Plane { .. }) {
        return out;
    }
    let ((pu0, pu1), (pv0, pv1)) = s.param_box();
    let bounded = |a: f64, b: f64| a > -1e4 && b < 1e4;
    let ((u0, u1), (v0, v1)) = match uv {
        Some(((fu0, fu1), (fv0, fv1))) => (if bounded(pu0, pu1) { (pu0, pu1) } else { (fu0, fu1) }, if bounded(pv0, pv1) { (pv0, pv1) } else { (fv0, fv1) }),
        None => ((pu0, pu1), (pv0, pv1)),
    };
    if bounded(u0, u1) && bounded(v0, v1) {
        for n in [16usize, 64] {
            let mut best = (f64::INFINITY, (u0, v0));
            for i in 0..=n {
                for j in 0..=n {
                    let (a, b) = (u0 + (u1 - u0) * i as f64 / n as f64, v0 + (v1 - v0) * j as f64 / n as f64);
                    let d = (s.eval(a, b) - p).norm_squared();
                    if d < best.0 {
                        best = (d, (a, b));
                    }
                }
            }
            out.push(s.project(p, Some(best.1)));
        }
    }
    let first = out[out.len() - 1];
    for h in [(u0, first.1), (u1, first.1), (first.0, v0), (first.0, v1)] {
        out.push(s.project(p, Some(h)));
    }
    out
}

/// A surface and the part of it a face covers: its uv polygons and their box.
#[derive(Debug, Clone)]
pub struct Patch {
    pub surf: Surface,
    pub polys: Vec<Vec<P2>>,
    pub uv: UvBox,
}

fn poly_box(polys: &[Vec<P2>]) -> UvBox {
    let mut ub = (f64::INFINITY, f64::NEG_INFINITY);
    let mut vb = (f64::INFINITY, f64::NEG_INFINITY);
    for q in polys.iter().flatten() {
        ub = (ub.0.min(q.x), ub.1.max(q.x));
        vb = (vb.0.min(q.y), vb.1.max(q.y));
    }
    (ub, vb)
}

impl Patch {
    /// Face `f` of `body`, trimmed by its loops.
    pub fn face(body: &Body, f: usize) -> Patch {
        let face = &body.faces[f];
        let polys = classify::face_polygons(body, face);
        let uv = poly_box(&polys);
        Patch { surf: face.surf.clone(), polys, uv }
    }

    /// Every face of `body`.
    pub fn faces(body: &Body) -> Vec<Patch> {
        (0..body.faces.len()).map(|f| Patch::face(body, f)).collect()
    }

    /// Face `f` of `body` as SMLib's `GlobalSurfaceIntersect` takes it: its surface over the face's
    /// uv domain, untrimmed (`SmFace::GetUVDomain`): the surface's whole range in a direction
    /// where that is bounded (a B-spline's, a meridian's or an extruded curve's range, an
    /// angle's turn; a cylinder's angle excepted), the face's extent where it isn't (a plane, a
    /// cylinder's length).
    pub fn domain(body: &Body, f: usize) -> Patch {
        let face = Patch::face(body, f);
        let ((u0, u1), (v0, v1)) = face.surf.param_box();
        let bounded = |a: f64, b: f64| a > -1e4 && b < 1e4;
        // (A cylinder's own face keeps its angle range: SMLib's cylinder domain is its sweep.)
        let whole = !matches!(face.surf, Surface::Cylinder { .. });
        let u = if whole && bounded(u0, u1) { (u0, u1) } else { face.uv.0 };
        let v = if whole && bounded(v0, v1) { (v0, v1) } else { face.uv.1 };
        Patch::rect(face.surf, (u, v))
    }

    /// Every face of `body` as SMLib intersects it ([`Patch::domain`]).
    pub fn domains(body: &Body) -> Vec<Patch> {
        (0..body.faces.len()).map(|f| Patch::domain(body, f)).collect()
    }

    /// The surface over the uv rectangle `uv` (an untrimmed face, `CreateFaceFromSurface`).
    pub fn rect(surf: Surface, uv: UvBox) -> Patch {
        let ((u0, u1), (v0, v1)) = uv;
        let polys = vec![vec![P2::new(u0, v0), P2::new(u1, v0), P2::new(u1, v1), P2::new(u0, v1)]];
        Patch { surf, polys, uv }
    }

    pub fn bbox(&self) -> Bbox {
        self.surf.patch_bbox(self.uv.0, self.uv.1)
    }

    /// Whether `p` (near the surface) lies in the patch, its boundary included.
    pub fn contains(&self, p: &P3) -> bool {
        self.contains_along(p, &std::cell::Cell::new(None))
    }

    /// [`Patch::contains`] for a point along a curve: the foot first from the foot of the point
    /// before (`hint`, updated), the global search only where that comes out far.
    pub fn contains_along(&self, p: &P3, hint: &std::cell::Cell<Option<(f64, f64)>>) -> bool {
        let hinted = hint.get().map(|h| self.surf.project(p, Some(h))).filter(|&(u, v)| (self.surf.eval(u, v) - p).norm() <= ON_TOL);
        let starts = match hinted {
            Some(uv) => vec![uv],
            None => feet(&self.surf, p, Some(self.uv)),
        };
        if let Some(&best) = starts.iter().min_by(|x, y| (self.surf.eval(x.0, x.1) - p).norm().total_cmp(&(self.surf.eval(y.0, y.1) - p).norm())) {
            hint.set(Some(best));
        }
        starts.into_iter().any(|(u, v)| {
            let d = (self.surf.eval(u, v) - p).norm();
            if d > 2.0 * ON_TOL {
                return false;
            }
            // A point past a bounded (B-spline) surface's edge projects onto the edge: on the
            // face's boundary only when it lies on the surface too.
            classify::periodic_candidates(&self.surf, u, v, &self.polys).into_iter().any(|uv| match classify::in_face(&self.polys, &self.surf, uv, 1e-8) {
                InFace::Inside => true,
                InFace::Boundary => d <= 1e-6 * (1.0 + p.coords.norm()),
                InFace::Outside => false,
            })
        })
    }
}

/// What intersecting found, over all pairs of faces.
#[derive(Debug, Default)]
pub struct Found {
    /// The pieces of the curves inside both faces, as polylines.
    pub pieces: Vec<Vec<P3>>,
    /// Their total length.
    pub length: f64,
    /// Isolated points (degenerate curves: touching points) inside both faces.
    pub points: Vec<P3>,
}

impl Found {
    /// Curves and points found.
    pub fn count(&self) -> usize {
        self.pieces.len() + self.points.len()
    }

    /// Distance from `p` to the nearest piece or point.
    pub fn distance(&self, p: &P3) -> f64 {
        let mut best = f64::INFINITY;
        for pc in &self.pieces {
            for w in pc.windows(2) {
                best = best.min(seg_dist(p, &w[0], &w[1]));
            }
            if let [q] = pc.as_slice() {
                best = best.min((q - p).norm());
            }
        }
        for q in &self.points {
            best = best.min((q - p).norm());
        }
        best
    }
}

/// Distance from `p` to the segment `ab`.
pub fn seg_dist(p: &P3, a: &P3, b: &P3) -> f64 {
    let d = b - a;
    let l2 = d.norm_squared();
    let t = if l2 > 0.0 { ((p - a).dot(&d) / l2).clamp(0.0, 1.0) } else { 0.0 };
    (a + d * t - p).norm()
}

/// The runs of [t0, t1] where `inside` holds, their ends found by bisection.
pub fn runs(t0: f64, t1: f64, n: usize, inside: impl Fn(f64) -> bool) -> Vec<(f64, f64)> {
    let ts: Vec<f64> = (0..=n).map(|i| t0 + (t1 - t0) * i as f64 / n as f64).collect();
    let ins: Vec<bool> = ts.iter().map(|&t| inside(t)).collect();
    let edge = |a: f64, b: f64, a_in: bool| {
        // The switch between a (inside or not) and b (the other).
        let (mut lo, mut hi) = (a, b);
        for _ in 0..50 {
            let m = 0.5 * (lo + hi);
            if inside(m) == a_in {
                lo = m;
            } else {
                hi = m;
            }
        }
        0.5 * (lo + hi)
    };
    let mut out = Vec::new();
    let mut start = if ins[0] { Some(t0) } else { None };
    for i in 1..=n {
        match (ins[i - 1], ins[i]) {
            (false, true) => start = Some(edge(ts[i - 1], ts[i], false)),
            (true, false) => {
                if let Some(s) = start.take() {
                    out.push((s, edge(ts[i - 1], ts[i], true)));
                }
            }
            _ => {}
        }
    }
    if let Some(s) = start {
        out.push((s, t1));
    }
    out
}

/// A curve's points at `n + 1` even parameters of [t0, t1].
pub fn polyline(c: &Curve, t0: f64, t1: f64, n: usize) -> Vec<P3> {
    (0..=n).map(|i| c.point(t0 + (t1 - t0) * i as f64 / n as f64)).collect()
}

/// Intersects every patch of `pa` with every patch of `pb` (`ssi::surface_surface`, crossing and
/// touching curves; a curve of no length is a touching point) and keeps what lies in both. Fails
/// when a curve inside both faces leaves either surface.
pub fn intersect_patches(pa: &[Patch], pb: &[Patch]) -> Result<Found, String> {
    let mut found = Found::default();
    for (i, a) in pa.iter().enumerate() {
        for (j, b) in pb.iter().enumerate() {
            let (ba, bb) = (a.bbox(), b.bbox());
            let size = ba.diagonal().max(bb.diagonal()).max(1.0);
            if !ba.grow(1e-6 * size).overlaps(&bb.grow(1e-6 * size)) {
                continue;
            }
            // The boxes' overlap.
            let region = Bbox { min: ba.min.sup(&bb.min), max: ba.max.inf(&bb.max) }.grow(1e-6 * size);
            let curves = ssi::surface_surface(&a.surf, a.uv, &b.surf, b.uv, &region);
            for (k, c) in curves.iter().enumerate() {
                let (t0, t1) = (c.t0.min(c.t1), c.t0.max(c.t1));
                // What lies in both faces (near both surfaces: a bounded surface's points
                // past its edge are in neither) must lie on both surfaces.
                // (Each surface's foot followed along the curve from the last, as a continuation
                // finds it; a global search where that comes out far.)
                let (ha, hb) = (std::cell::Cell::new(None), std::cell::Cell::new(None));
                let (ca, cb) = (std::cell::Cell::new(None), std::cell::Cell::new(None));
                let on_both = |p: &P3| -> Result<(), String> {
                    let (da, db) = (dist_along(&a.surf, p, &ha), dist_along(&b.surf, p, &hb));
                    if da > ON_TOL || db > ON_TOL {
                        return Err(format!("faces {i}×{j}, curve {k}: the point {p:?} is {da:.1e} off the first surface and {db:.1e} off the second"));
                    }
                    Ok(())
                };
                let both = |t: f64| {
                    let p = c.c.point(t);
                    a.contains_along(&p, &ca) && b.contains_along(&p, &cb)
                };
                if c.c.length(t0, t1) <= 1e-9 {
                    // A degenerate curve: a point.
                    let p = c.c.point(t0);
                    if a.contains(&p) && b.contains(&p) {
                        on_both(&p)?;
                        found.points.push(p);
                    }
                    continue;
                }
                for (ra, rb) in runs(t0, t1, 1024, both) {
                    let l = c.c.length(ra, rb);
                    if l <= 1e-9 {
                        let p = c.c.point(ra);
                        on_both(&p)?;
                        found.points.push(p);
                        continue;
                    }
                    let pl = polyline(&c.c, ra, rb, 256);
                    for p in pl.iter().step_by(4) {
                        // (Between the run's samples the curve may leave a face and come back.)
                        if a.contains(p) && b.contains(p) {
                            on_both(p)?;
                        }
                    }
                    found.length += l;
                    found.pieces.push(pl);
                }
            }
        }
    }
    Ok(found)
}

/// What SMLib gives: whether there is any intersection (its test's count, as none or some),
/// the total length of its curves and points along them (the oracle's).
pub struct Want<'a> {
    pub any: bool,
    pub length: Option<f64>,
    pub samples: &'a [[f64; 3]],
}

/// Checks what intersecting found against SMLib's.
pub fn check_found(f: &Found, w: &Want) -> Result<(), String> {
    if (f.count() > 0) != w.any {
        return Err(format!(
            "{} curves and {} points (length {:.6}), SMLib finds {}",
            f.pieces.len(),
            f.points.len(),
            f.length,
            if w.any { "some" } else { "none" }
        ));
    }
    if let Some(l) = w.length {
        if (f.length - l).abs() > LEN_TOL * l.max(1.0) {
            return Err(format!("total length {:.6}, SMLib gives {l:.6} ({} curves, {} points)", f.length, f.pieces.len(), f.points.len()));
        }
    }
    for (k, s) in w.samples.iter().enumerate() {
        let p = P3::new(s[0], s[1], s[2]);
        let d = f.distance(&p);
        if d > SAMPLE_TOL {
            return Err(format!("SMLib's sample {k} {p:?} is {d:.1e} from our curves"));
        }
    }
    Ok(())
}

/// Distinct points (within `tol` of each other).
pub fn distinct(pts: &[P3], tol: f64) -> Vec<P3> {
    let mut out: Vec<P3> = Vec::new();
    for p in pts {
        if !out.iter().any(|q| (q - p).norm() <= tol) {
            out.push(*p);
        }
    }
    out
}
